"""Independent native-executable oracle, regenerated by scripts/generate_salinity_oracle.py."""
import json
from pathlib import Path

import jax
import numpy as np
import pytest

from aquacrop_jax.salinity import (compartment_conductivity, concentrate_salts,
                                   initialize_salt, salt_geometry, salinity_stress)
from aquacrop_jax.salt_transport import salt_transport_step
from aquacrop_jax.soil import discretize_profile, read_soil_profile, resize_for_root_depth

FIXTURE = json.loads((Path(__file__).parent / 'fixtures/salinity_fortran73.json').read_text())


@pytest.mark.parametrize('case', FIXTURE['cases'], ids=['two-cells', 'eleven-cells'])
def test_transport_against_native_fortran_daily_output(case):
    soil = read_soil_profile(Path(__file__).parents[2] / 'aquacrop-fortran/testcase/DATA/Ottawa.SOL')
    dz = np.asarray(resize_for_root_depth(soil, discretize_profile(soil), 3.).thickness)
    theta = np.full(12, .29)
    geometry = salt_geometry([46.] * 12, [29.] * 12, [case['ksat']] * 12)
    state = initialize_salt(case['initial_ece'], theta, dz, np.zeros(12), 46., geometry)
    operation = jax.jit(salt_transport_step)
    # At 11 cells, the third snapshot crosses a salt-cell edge. Rounded WC
    # cannot recover which side its full-precision flux occupied; that step
    # is checked against the native object probe in test_salt_probe.py.
    records = case['records'] if case['ksat'] == 1200. else case['records'][:2]
    for row in records:
        updated = np.asarray([row[f'theta{i:02d}_pct'] for i in range(1, 13)]) / 100.
        # Zero ET/rain: compartment flux follows directly from water storage.
        # Native WC is rounded to 0.1 vol%, so fluxes have a known quantization error.
        flux = row['infiltration'] - np.cumsum((updated - theta) * dz * 1000.)
        flux = np.maximum(flux, 0.)
        result = operation(state, updated, flux, dz, np.zeros(12), 46., 29., geometry,
            infiltrated_irrigation=row['infiltration'], irrigation_ec=case['irrigation_ec'])
        state = concentrate_salts(result.state, updated, dz, np.zeros(12), geometry)
        actual = np.asarray(compartment_conductivity(state, updated, dz, np.zeros(12), 46., 29.).ece)
        expected = [row[f'ece{i:02d}'] for i in range(1, 13)]
        assert actual == pytest.approx(expected, abs=.08)
        total = float(np.sum(np.asarray(state.dissolved + state.deposited))) / 100.
        assert total == pytest.approx(row['salt_total'], abs=.05)
        assert float(result.drained_g_m2) / 100. == pytest.approx(row['salt_out'], abs=.05)
        assert float(result.residual_g_m2) == pytest.approx(0., abs=1e-9)
        # StSalt is an integer percentage derived from printed root-zone ECe.
        stress = float((1. - salinity_stress(row['root_ece'], 2., 16.)) * 100.)
        assert stress == pytest.approx(row['salt_stress'], abs=.55)
        theta = updated
